"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Waarde tussen 0 en `max`. Laat weg voor een onbepaalde balk. */
  value?: number;
  max?: number;
  tone?: "accent" | "green" | "amber" | "red" | "blue";
  size?: "sm" | "md" | "lg";
  /** Label boven de balk. */
  label?: React.ReactNode;
  /** Toont het percentage rechtsboven. */
  showValue?: boolean;
}

/** Progress — voortgangsbalk, bepaald of onbepaald. */
export const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(function Progress(
  { value, max = 100, tone = "accent", size = "md", label, showValue, className, ...rest },
  ref
) {
  const indeterminate = value === undefined || value === null;
  const percent = indeterminate ? 0 : Math.min(100, Math.max(0, (value / max) * 100));

  return (
    <div ref={ref} className={cn("lui-progress-wrap", className)} {...rest}>
      {(label || showValue) && (
        <div className="lui-progress-head">
          {label && <span className="lui-progress-label">{label}</span>}
          {showValue && !indeterminate && (
            <span className="lui-progress-value">{Math.round(percent)}%</span>
          )}
        </div>
      )}
      <div
        className={cn("lui-progress", `lui-progress-${size}`, `lui-progress-${tone}`)}
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={indeterminate ? undefined : value}
      >
        <div
          className={cn("lui-progress-bar", indeterminate && "lui-progress-bar-indeterminate")}
          style={indeterminate ? undefined : { width: `${percent}%` }}
        />
      </div>
    </div>
  );
});

export interface ProgressCircleProps extends React.HTMLAttributes<HTMLDivElement> {
  value?: number;
  max?: number;
  size?: number;
  thickness?: number;
  tone?: "accent" | "green" | "amber" | "red" | "blue";
  /** Toont het percentage in het midden. */
  showValue?: boolean;
}

/** ProgressCircle — ronde voortgangsindicator. */
export const ProgressCircle = React.forwardRef<HTMLDivElement, ProgressCircleProps>(
  function ProgressCircle(
    { value = 0, max = 100, size = 56, thickness = 5, tone = "accent", showValue, className, ...rest },
    ref
  ) {
    const percent = Math.min(100, Math.max(0, (value / max) * 100));
    const radius = (size - thickness) / 2;
    const circumference = 2 * Math.PI * radius;

    return (
      <div
        ref={ref}
        className={cn("lui-progress-circle", `lui-progress-${tone}`, className)}
        style={{ width: size, height: size }}
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={max}
        aria-valuenow={value}
        {...rest}
      >
        <svg width={size} height={size}>
          <circle
            className="lui-progress-circle-track"
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={thickness}
            fill="none"
          />
          <circle
            className="lui-progress-circle-bar"
            cx={size / 2}
            cy={size / 2}
            r={radius}
            strokeWidth={thickness}
            fill="none"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={circumference - (percent / 100) * circumference}
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        </svg>
        {showValue && <span className="lui-progress-circle-value">{Math.round(percent)}%</span>}
      </div>
    );
  }
);

/* ============================ Progress ============================ */
.lui-progress-wrap { --lui-progress-color: var(--accent); display: flex; flex-direction: column; gap: 7px; width: 100%; }
.lui-progress-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.lui-progress-label { font-size: 13px; font-weight: 550; color: var(--text-2); }
.lui-progress-value { font-size: var(--fs-sm); font-weight: 650; color: var(--text); font-family: var(--mono); }

.lui-progress {
  --lui-progress-color: var(--accent);
  position: relative; width: 100%; height: 8px; overflow: hidden;
  background: var(--surface-3); border-radius: var(--r-full);
}
.lui-progress-sm { height: 5px; }
.lui-progress-lg { height: 12px; }

.lui-progress-accent { --lui-progress-color: var(--accent); }
.lui-progress-green { --lui-progress-color: var(--green); }
.lui-progress-amber { --lui-progress-color: var(--amber); }
.lui-progress-red { --lui-progress-color: var(--red); }
.lui-progress-blue { --lui-progress-color: var(--blue); }

.lui-progress-bar {
  height: 100%; border-radius: inherit;
  background: var(--lui-progress-color);
  transition: width .45s var(--ease-out);
}
.lui-progress-bar-indeterminate {
  width: 38%; position: absolute; left: 0;
  animation: lui-progress-slide 1.15s var(--ease) infinite;
}
@keyframes lui-progress-slide {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(365%); }
}

/* ---------- Circle ---------- */
.lui-progress-circle { position: relative; display: inline-grid; place-items: center; }
.lui-progress-circle svg { position: absolute; inset: 0; }
.lui-progress-circle-track { stroke: var(--surface-3); }
.lui-progress-circle-bar {
  stroke: var(--lui-progress-color, var(--accent));
  transition: stroke-dashoffset .5s var(--ease-out);
}
.lui-progress-circle-value {
  font-size: var(--fs-sm); font-weight: 700; color: var(--text); font-family: var(--mono);
}
